# 2D grid — Y distributed across SMs via autotune
@triton.autotune(
    configs=[
        triton.Config({'XBLOCK': 8,  'YBLOCK': 64},  num_warps=4),
        triton.Config({'XBLOCK': 8,  'YBLOCK': 128}, num_warps=4),
        triton.Config({'XBLOCK': 16, 'YBLOCK': 64},  num_warps=4),
        triton.Config({'XBLOCK': 32, 'YBLOCK': 32},  num_warps=4),
        triton.Config({'XBLOCK': 8,  'YBLOCK': 256}, num_warps=8),
    ],
    key=['ynumel', 'xnumel'],
)
@triton.jit
def kernel(..., ynumel, xnumel, YBLOCK, XBLOCK):
    yoffset = tl.program_id(1) * YBLOCK  # pure 2D
    ...

def launch(...):
    grid = lambda META: (
        cdiv(xnumel, META['XBLOCK']),
        cdiv(ynumel, META['YBLOCK']),
    )
    kernel[grid](...)  # XBLOCK/YBLOCK injected by autotune

# 2D grid — both X and Y dimensions parallelized
@triton.autotune(configs=[
    triton.Config({'XBLOCK': 32, 'YBLOCK': 32}, num_warps=4, num_stages=1),
    triton.Config({'XBLOCK': 128, 'YBLOCK': 32}, num_warps=8, num_stages=1),
    # ... more configs
], key=['ynumel', 'xnumel'])
